<script setup lang="ts">
import {ref,reactive,computed} from 'vue'
import {Check,Plus,SlidersHorizontal,ShieldCheck,Download,Upload,Database,FileCheck,LoaderCircle,Pencil,Heart,LockKeyhole,Info,Sun,Moon,X} from 'lucide-vue-next'
import {sortBodyRows} from '../bodyMetrics'
import {state,api,saveSettings,refresh} from '../api'
import type {Row} from '../types'
import {shortDate,localNow,collectionLabels} from '../types'
const emit=defineEmits<{edit:[collection:string,row?:Row,preset?:Record<string,any>];changed:[];notify:[message:string];lock:[];view:[page:string]}>()
const form=reactive({...state.settings}),busy=ref(false),error=ref(''),backupFile=ref<any>(null),preview=ref<any>(null),backupName=ref(''),fileInput=ref<HTMLInputElement>(),restoreOpen=ref(false)
const latestBody=computed(()=>sortBodyRows(state.collections.body||[])[0])
async function save(){busy.value=true;error.value='';try{await saveSettings(form);emit('notify','偏好已保存。');emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function downloadBackup(){busy.value=true;error.value='';try{const data=await api('/backup');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`自记-完整备份-${localNow().replaceAll(':','-')}.json`;a.click();URL.revokeObjectURL(a.href);emit('notify','备份已下载，请妥善保管。')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function selectBackup(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>50*1024*1024)throw new Error('文件超过 50 MB，请先检查备份文件。');const data=JSON.parse(await file.text());const result=await api('/backup/preview',{method:'POST',body:JSON.stringify(data)});backupFile.value=data;backupName.value=file.name;preview.value=result;restoreOpen.value=true}catch(e){error.value=e instanceof SyntaxError?'文件不是有效的 JSON 备份，请重新选择。':(e as Error).message}finally{busy.value=false;if(fileInput.value)fileInput.value.value=''}}
async function restore(){busy.value=true;error.value='';try{await api('/backup/restore',{method:'POST',body:JSON.stringify({backup:backupFile.value,mode:'merge'})});await refresh();emit('changed');emit('notify','备份已合并恢复，数据已刷新。');restoreOpen.value=false;backupFile.value=null;preview.value=null}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="settings-page"><div class="settings-grid"><section class="panel settings-section"><header><span class="icon-tile mint"><SlidersHorizontal :size="21"/></span><div><h3>按自己的方式使用</h3><p>外观和提醒，随时可以调整。</p></div></header><form @submit.prevent="save"><div class="settings-row"><div><strong>界面主题</strong><small>深色沉静，浅色清晰</small></div><div class="segmented"><button type="button" :class="{active:form.theme==='dark'}" @click="form.theme='dark'"><Moon :size="15"/>深色</button><button type="button" :class="{active:form.theme==='light'}" @click="form.theme='light'"><Sun :size="15"/>浅色</button></div></div><label class="settings-row"><div><strong>减少动效</strong><small>降低动画强度，保留完整信息</small></div><input class="toggle" type="checkbox" v-model="form.reducedMotion"/></label><label class="settings-row"><div><strong>默认隐私遮挡</strong><small>遮挡数字与记录，只影响显示</small></div><input class="toggle" type="checkbox" v-model="form.hidden"/></label><label class="field"><span>提醒方式</span><select v-model="form.reminderMode"><option value="OFF">只记录</option><option value="GENTLE">温和提醒</option><option value="ACTIVE">主动帮助减少</option></select></label><div class="fields-grid"><label class="field"><span>安静时段开始</span><input type="time" v-model="form.quietStart"/></label><label class="field"><span>安静时段结束</span><input type="time" v-model="form.quietEnd"/></label><label class="field"><span>每天最多提醒次数</span><input type="number" v-model.number="form.dailyReminderLimit" min="0" max="20"/></label><label class="field"><span>近期饮酒观察窗口 · 小时</span><input type="number" v-model.number="form.recentAlcoholHours" min="1" max="168"/></label></div><p class="hint">观察窗口只用于查找相邻记录，不是医学安全时限。应用关闭时不发送提醒。</p><footer><button class="button primary" :disabled="busy"><Check :size="17"/>保存偏好</button></footer></form></section>
<div class="settings-stack"><section class="panel settings-section"><header><span class="icon-tile alcohol"><Heart :size="21"/></span><div><h3>身体参数</h3><p>在身体数据页查看体重、体脂率、BMI 和测量历史。</p></div><button class="icon-button" title="新增身体测量" @click="emit('edit','body')"><Plus :size="18"/></button></header><button class="text-link" @click="emit('view','body')">打开身体数据仪表盘 →</button><div v-if="latestBody" class="body-metrics sensitive"><div><strong>{{latestBody.heightCm??'—'}}<small>cm</small></strong><span>身高</span></div><div><strong>{{latestBody.weightKg??'—'}}<small>kg</small></strong><span>体重</span></div><div><strong>{{latestBody.age??'—'}}<small>岁</small></strong><span>年龄</span></div></div><div v-else class="empty-state compact"><p>尚未添加身体参数。你可以正常记录，个人化估算会等待资料完整。</p><button class="button secondary" @click="emit('edit','body')"><Plus :size="16"/>添加测量</button></div><div v-if="latestBody" class="section-line"><span class="muted small">测量于 {{shortDate(latestBody.measuredAt)}}</span><button class="text-link" @click="emit('edit','body',latestBody)"><Pencil :size="14"/>修正这次测量</button></div></section><section class="panel settings-section"><header><span class="icon-tile"><ShieldCheck :size="21"/></span><div><h3>本机与隐私</h3><p>个人记录不会上传到商品资料服务。</p></div></header><p class="muted small">应用仅在当前电脑运行。隐私按钮负责遮挡显示；离开电脑时，可以锁定应用。</p><button class="button secondary full-width" @click="emit('lock')"><LockKeyhole :size="16"/>立即锁定应用</button></section></div></div>
<section class="panel settings-section backup-section"><header><span class="icon-tile alcohol"><Database :size="21"/></span><div><h3>备份与恢复</h3><p>完整备份便于迁移或恢复。导出的文件包含个人数据，请妥善保存。</p></div></header><div class="backup-actions"><button class="backup-action" :disabled="busy" @click="downloadBackup"><Download :size="23"/><div><strong>导出完整备份</strong><span>下载带版本信息的 JSON 文件</span></div><span>导出</span></button><button class="backup-action" :disabled="busy" @click="fileInput?.click()"><Upload :size="23"/><div><strong>导入并恢复备份</strong><span>先检查内容，再确认合并</span></div><span>选择文件</span></button><input ref="fileInput" class="visually-hidden" type="file" accept=".json,application/json" @change="selectBackup"/></div><p v-if="error" class="error-box" role="alert">{{error}}</p></section>
<div v-if="restoreOpen" class="overlay centered" @click.self="restoreOpen=false"><section class="modal wide-modal"><header><span class="icon-tile alcohol"><FileCheck :size="22"/></span><button class="icon-button" title="关闭" @click="restoreOpen=false"><X :size="20"/></button></header><h2>检查备份后再恢复</h2><p>{{backupName}}</p><div class="backup-summary"><div><strong>{{preview?.newRecords||0}}</strong><span>新增记录</span></div><div><strong>{{preview?.existingRecords||0}}</strong><span>已有记录</span></div><div><strong>{{preview?.conflicts?.length||0}}</strong><span>内容冲突</span></div></div><div class="table-scroll"><table><thead><tr><th>数据类别</th><th>新增</th><th>已有</th><th>冲突</th></tr></thead><tbody><tr v-for="(count,key) in preview?.counts||{}" :key="key"><td>{{collectionLabels[String(key)]||key}}</td><td>{{count.new}}</td><td>{{count.existing}}</td><td>{{count.conflicts}}</td></tr></tbody></table></div><p v-for="(notice,i) in preview?.warnings||[]" :key="`notice-${i}`" class="hint">{{notice}}</p><p v-for="(problem,i) in preview?.errors||[]" :key="i" class="error-box">{{problem}}</p><p class="hint">{{preview?.policy||'同编号的本机记录保持不变，只导入新的记录；恢复前自动保留当前备份。'}}</p><p v-if="error" class="error-box">{{error}}</p><footer><button class="button secondary" @click="restoreOpen=false">取消</button><button class="button primary" :disabled="busy||preview?.valid!==true" @click="restore"><LoaderCircle v-if="busy" :size="17" class="spin"/>确认合并恢复</button></footer></section></div></div></template>
